import { _decorator, assetManager, Camera, Component, director, ImageAsset, Rect, screen, sys, view } from 'cc';
import { PREVIEW } from 'cc/env';
import GameConfigManager from '../config/GameConfigManager';

const { ccclass } = _decorator;

// 黑邊背景圖 放在遊戲包裡
const BACKDROP_MAIN_PATH = 'resources/Images/backdrop_main';
const BACKDROP_FREE_PATH = 'resources/Images/backdrop_free';

/**
 * 是否固定比例 entry 或殼頁會設旗標 單獨預覽沒有旗標 桌面瀏覽器直接視為固定比例
 */
export function isFixedRatio(): boolean {
    if (!sys.isBrowser) return false;
    if ((globalThis as Record<string, unknown>).__subGameFixedRatio__ === true) return true;
    return PREVIEW && !sys.isMobile && window.parent === window;
}

/** 固定比例時把所有相機裁在設計框內 並在黑邊鋪背景圖 不是固定比例就什麼都不做 */
@ccclass('1001/FixedRatioFrame')
export class FixedRatioFrame extends Component {
    private static instance: FixedRatioFrame | null = null;

    private backdropEl: HTMLDivElement | null = null;
    private backdropUrls: { main: string; free: string } | null = null;
    private backdropFree = false;

    /**
     * 切換一般或免費遊戲的黑邊背景圖
     *
     * @param free 是否為免費遊戲
     */
    public static setFree(free: boolean): void {
        const frame = FixedRatioFrame.instance;
        if (!frame) return;
        frame.backdropFree = free;
        frame.applyBackdrop();
    }

    protected override onLoad(): void {
        FixedRatioFrame.instance = this;
        view.on('design-resolution-changed', this.refit, this);
        this.refit();
    }

    protected override start(): void {
        void this.loadBackdrop();
    }

    protected override onDestroy(): void {
        view.off('design-resolution-changed', this.refit, this);
        this.applyRect(new Rect(0, 0, 1, 1));
        this.backdropEl?.remove();
        this.backdropEl = null;
        if (FixedRatioFrame.instance === this) FixedRatioFrame.instance = null;
    }

    private refit(): void {
        if (!isFixedRatio()) {
            this.applyRect(new Rect(0, 0, 1, 1));
            return;
        }
        const design = view.getDesignResolutionSize();
        const win = screen.windowSize;
        const designAspect = design.width / design.height;
        const winAspect = win.width / win.height;
        const rect = new Rect(0, 0, 1, 1);
        if (winAspect > designAspect) {
            rect.width = designAspect / winAspect;
            rect.x = (1 - rect.width) / 2;
        } else {
            rect.height = winAspect / designAspect;
            rect.y = (1 - rect.height) / 2;
        }
        this.applyRect(rect);
    }

    private applyRect(rect: Rect): void {
        const scene = director.getScene();
        if (!scene) return;
        for (const camera of scene.getComponentsInChildren(Camera)) {
            // 畫到貼圖的相機不是畫到螢幕 不裁
            if (camera.targetTexture) continue;
            camera.rect = rect;
            // 引擎改 rect 不會重算寬高比 要自己重設一次
            const inner = camera.camera;
            if (inner?.window) inner.resize(inner.window.width, inner.window.height);
        }
    }

    private async loadBackdrop(): Promise<void> {
        if (!isFixedRatio()) return;
        const bundle = assetManager.getBundle(GameConfigManager.GAMEID);
        const paths = [BACKDROP_MAIN_PATH, BACKDROP_FREE_PATH];
        if (!bundle) {
            console.warn('[FixedRatioFrame] 找不到遊戲 bundle 沒有黑邊背景圖', GameConfigManager.GAMEID);
            return;
        }
        const missing = paths.filter((path) => !bundle.getInfoWithPath(path, ImageAsset));
        if (missing.length) {
            console.warn('[FixedRatioFrame] bundle 內找不到黑邊背景圖', missing);
            return;
        }
        try {
            const [main, free] = await Promise.all(
                paths.map(
                    (path) =>
                        new Promise<string>((resolve, reject) => {
                            bundle.load(path, ImageAsset, (error, asset) => (error ? reject(error) : resolve(asset.nativeUrl)));
                        })
                )
            );
            if (!this.isValid) return;
            this.backdropUrls = { main, free };
            console.log('[FixedRatioFrame] 黑邊背景圖已載入', main, free);
            this.applyBackdrop();
        } catch (error) {
            console.warn('[FixedRatioFrame] 讀取黑邊背景圖失敗 略過', error);
        }
    }

    private applyBackdrop(): void {
        const urls = this.backdropUrls;
        if (!urls) return;
        if (!this.backdropEl) {
            const el = document.createElement('div');
            el.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:100%;pointer-events:none;z-index:-1;background-size:cover;background-position:center;background-repeat:no-repeat';
            document.body.insertBefore(el, document.body.firstChild);
            this.backdropEl = el;
        }
        this.backdropEl.style.backgroundImage = `url("${(this.backdropFree ? urls.free : urls.main).replace(/"/g, '%22')}")`;
        // 另一張先載進快取 切換時不會閃
        new Image().src = this.backdropFree ? urls.main : urls.free;
    }
}
